  /* ============================================================
     FUNÇÕES AUXILIARES
     ============================================================ */
  
  /**
   * Retorna lista de cidades de um país
   */
  export function getCidadesDoPais(pais) {
    if (!pais) return [];
    const key = Object.keys(CIDADES_POR_PAIS).find(
      k => k.toLowerCase() === pais.toLowerCase()
    );
    return key ? CIDADES_POR_PAIS[key] : [];
  }
  
  /**
   * Retorna lista de TODOS os países disponíveis
   */
  export function getPaisesDisponiveis() {
    return Object.keys(CIDADES_POR_PAIS);
  }
  
  /**
   * Verifica se uma cidade pertence a um país
   */
  export function cidadePertenceAoPais(cidade, pais) {
    const cidades = getCidadesDoPais(pais);
    return cidades.some(c => c.toLowerCase() === cidade.toLowerCase());
  }
  
  /**
   * Filtra destinos que já foram usados, evitando duplicatas
   */
  export function filtrarDuplicatas(lista, jaUsados = []) {
    const vistos = new Set(jaUsados.map(n => n.toLowerCase().trim()));
    return lista.filter(cidade => {
      const nome = cidade.toLowerCase().trim();
      if (vistos.has(nome)) return false;
      vistos.add(nome);
      return true;
    });
  }
  
  /**
   * Sorteia N cidades de um país
   */
  export function sortearCidades(pais, quantidade = 5, jaUsados = []) {
    const cidades = getCidadesDoPais(pais);
    const disponiveis = filtrarDuplicatas(cidades, jaUsados);
    const embaralhadas = [...disponiveis].sort(() => Math.random() - 0.5);
    return embaralhadas.slice(0, quantidade);
  }
  
